from collections import defaultdict

def transform(grid):
    h,w=len(grid),len(grid[0])
    cells=defaultdict(list)
    for i,row in enumerate(grid):
        for j,v in enumerate(row):
            if v: cells[v].append((i,j))
    # global slope: majority over colors whose cells lie on a constant j-i line
    sp=0
    for c,cs in cells.items():
        if len(cs)>1:
            if len({j-i for i,j in cs})==1: sp+=1
            elif len({i+j for i,j in cs})==1: sp-=1
    d=1 if sp>=0 else -1
    offs={c:{(j-i) if d==1 else (i+j) for i,j in cs} for c,cs in cells.items()}
    P=1
    while any(a&b for a in offs.values() for b in offs.values() if a is not b) or True:
        ok=all(not(oa&ob) for ca,oa in offs.items() for cb,ob in offs.items() if ca!=cb)
        if ok: break
        P+=1
    rm={}
    for c,o in offs.items():
        for v in o: rm[v%P]=c
    return [[rm.get(((j-i) if d==1 else (i+j))%P,0) for j in range(w)] for i in range(h)]

